'use strict';
const backgroundPresets=[['햇살과 올리브','background-01'],['세이지 기프트','background-02'],['작은 데이지','background-03'],['포근한 쉼표','background-04'],['마음을 포장해요','background-05'],['함께 준비하는 온기','background-06'],['따뜻한 한 잔','background-07'],['초록빛 여유','background-08'],['마주 보는 마음','background-09'],['함께하는 우리 · 실사','real-community']];
const bannerPresets=[['함께하는 바자회','bazaar'],['마음을 담은 선물','hero'],['좋은 물건의 새 시작','objects'],['방긋한 이웃','people'],['기부로 이어지는 손길','community'],['함께 준비하는 나눔','banner-06'],['전해지는 따뜻한 마음','banner-07'],['우리 동네 주말 바자회','banner-08'],['방긋 라이브 스튜디오','banner-09'],['마음을 잇는 봉사 · 실사','real-volunteers']];
const avatarNames=['모찌 토끼','꿀잠 곰','살구 고양이','몽실 강아지','단풍 여우','포근 판다','유칼 코알라','콩알 햄스터','동글 수달','빙수 펭귄','햇살 병아리','도담 오리','초록 개구리','용감 사자','줄무늬 호랑이','복숭아 돼지','솜솜 양','우유 젖소','밤톨 라쿤','새싹 사슴','도토리 다람쥐','밤송 고슴도치','하품 하마','구름 코끼리','파도 물개','느긋 카피바라','방긋 쿼카','별빛 부엉이','마시멜로 알파카','새싹 공룡'];
const uploadedImages=new Map(),designViews=new Map();
let baseBrandPanel='',avatarDraft=null,avatarPrevious=null;
const avatarPath=n=>'/assets/avatars/avatar-'+String(n).padStart(2,'0')+'.svg';
function randomAvatar(except){const values=new Uint32Array(1);crypto.getRandomValues(values);const options=Array.from({length:30},(_,i)=>i+1).filter(n=>n!==except);return options[values[0]%options.length]}
function accountKey(){return MarketCore.accountId(db)}
function accountProfile(){const key=accountKey();db.accountProfiles??={};db.accountProfiles[key]??={avatar:randomAvatar()};return db.accountProfiles[key]}
function avatarHTML(id,cls=''){const n=Math.min(30,Math.max(1,Number(id)||1)),col=(n-1)%6,row=Math.floor((n-1)/6);return `<span class="character-avatar animal-avatar ${cls}" role="img" aria-label="${avatarNames[n-1]} 프로필" style="background-position:${col*20}% ${row*25}%"></span>`}
function seedDesign(scope){const orgScope=scope.startsWith('org:'),o=orgScope?org(scope.slice(4)):null,index=orgScope?Math.max(0,db.orgs.findIndex(item=>item.id===o.id)):0;return {catalogVersion:2,backgrounds:backgroundPresets.map(([label,file],i)=>({id:'bg'+(i+1),label,file,source:file.startsWith('real-')?'photo':'generated',alt:label+' 여백 이미지',x:50,y:60})),banners:bannerPresets.map(([label,file],i)=>({id:'bn'+(i+1),label,file,source:file.startsWith('real-')?'photo':'generated',alt:label+' 배너 이미지',x:50,y:50})),backgroundId:'bg'+((index%10)+1),bannerId:'bn'+(Math.max(0,bannerPresets.findIndex(p=>p[1]===o?.cover))+1),heroSelections:['bn1','bn2','bn3','bn4'],veil:orgScope?46:58}}
function designFor(scope){db.designs??={};db.designs[scope]??=seedDesign(scope);const design=db.designs[scope];if(!design.catalogVersion){for(const kind of ['backgrounds','banners']){const original=kind==='backgrounds'?'background-10':'banner-10',slot=design[kind][9];if(slot&&!slot.uploadId&&slot.file===original)Object.assign(slot,seedDesign(scope)[kind][9]);for(const item of design[kind])item.source??=item.file.startsWith('real-')?'photo':'generated'}design.catalogVersion=2}return design}
function scopeForEditor(){return db.role==='admin'?'site':db.role==='agency'?'org:'+db.orgId:null}
function canEditScope(scope){return scope&&scope===scopeForEditor()}
function selectedBackground(design){return design.backgrounds.find(item=>item.id===design.backgroundId)||design.backgrounds[0]}
function selectedBanner(design){return design.banners.find(item=>item.id===design.bannerId)||design.banners[0]}
function mediaSource(slot){return slot?.uploadId&&uploadedImages.has(slot.uploadId)?uploadedImages.get(slot.uploadId):asset(slot?.file||'people')}
function viewFor(scope){if(!designViews.has(scope))designViews.set(scope,{kind:'backgrounds',index:0,target:0});return designViews.get(scope)}
function ensureDesignData(){db.accountProfiles??={};for(const key of ['buyer','individual','company','admin',...db.orgs.map(o=>'agency:'+o.id)])db.accountProfiles[key]??={avatar:randomAvatar()};designFor('site');for(const o of db.orgs)designFor('org:'+o.id)}
function openImageDatabase(){return new Promise((resolve,reject)=>{if(!window.indexedDB){reject(new Error('이 브라우저에서 이미지 저장을 사용할 수 없습니다.'));return}const req=indexedDB.open('banggeut-design-images',1);req.onupgradeneeded=()=>req.result.createObjectStore('images',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function loadUploadedImages(){try{const idb=await openImageDatabase();const tx=idb.transaction('images','readonly');const req=tx.objectStore('images').getAll();req.onsuccess=()=>{for(const row of req.result){if(!uploadedImages.has(row.id))uploadedImages.set(row.id,URL.createObjectURL(row.blob))}idb.close();if(req.result.length)render()};req.onerror=()=>idb.close()}catch{}}
async function storeUploadedImage(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('JPG, PNG 또는 WebP 이미지를 선택해 주세요.');if(file.size>12*1024*1024)throw new Error('12MB 이하의 이미지를 선택해 주세요.');const bitmap=await createImageBitmap(file);if(bitmap.width<200||bitmap.height<150){bitmap.close();throw new Error('가로 200px, 세로 150px 이상의 이미지를 선택해 주세요.')}const ratio=Math.min(1,1800/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.88));if(!blob)throw new Error('이미지를 불러오지 못했습니다.');const id='upload-'+crypto.randomUUID(),idb=await openImageDatabase();await new Promise((resolve,reject)=>{const tx=idb.transaction('images','readwrite');tx.objectStore('images').put({id,blob});tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)});idb.close();uploadedImages.set(id,URL.createObjectURL(blob));return id}
function profileSettings(){const p=accountProfile();return `<section class="profile-settings-card"><div class="profile-setting-intro">${avatarHTML(p.avatar,'large')}<div><span class="section-overline">MY BANGGEUT CHARACTER</span><h3>나를 닮은 방긋 친구</h3><p>${esc(avatarNames[p.avatar-1])} · 총 30종</p></div></div><p class="small muted">처음에는 랜덤으로 만나요. 마음에 드는 친구로 언제든 바꿔 보세요.${db.role==='agency'?'<br>담당자 계정 프로필이며 기관 로고는 그대로 유지됩니다.':''}</p><div class="button-group">${btn('avatar-picker',icon('smile')+' 캐릭터 선택','secondary-btn')}${btn('avatar-random-now','랜덤으로 바꾸기','secondary-btn')}</div></section>`}
function openAvatarPicker(){avatarPrevious=accountProfile().avatar;avatarDraft=avatarPrevious;openModal('당신의 방긋 친구를 골라요',`<div class="avatar-picker-head">${avatarHTML(avatarDraft,'large')}<div><strong id="avatar-selected-name">${esc(avatarNames[avatarDraft-1])}</strong><p>프로필 캐릭터 30종${db.role==='agency'?'<br>기관 로고와는 별도예요.':''}</p></div>${btn('avatar-draft-random','랜덤','pill-btn')}</div><div class="avatar-picker-grid">${avatarNames.map((name,i)=>btn('avatar-draft-select',avatarHTML(i+1)+`<span>${name}</span>`,'avatar-choice '+(avatarDraft===i+1?'selected':''),`data-avatar="${i+1}" aria-label="${name} 선택" aria-pressed="${avatarDraft===i+1}"`)).join('')}</div><div class="avatar-modal-actions">${btn('close-modal','취소','secondary-btn')}${btn('avatar-commit','이 친구로 저장','primary-btn green')}</div>`,true)}
function updateAvatarDraft(n){avatarDraft=n;$('#avatar-selected-name').textContent=avatarNames[n-1];$('#modal-root .avatar-picker-head .character-avatar').outerHTML=avatarHTML(n,'large');document.querySelectorAll('.avatar-choice').forEach(el=>{const selected=Number(el.dataset.avatar)===n;el.classList.toggle('selected',selected);el.setAttribute('aria-pressed',String(selected))})}
function buyerProfilePage(){return header()+`<div class="page-head"><div class="back-head"><a href="#/my" class="icon-btn" aria-label="마이 방긋으로">${icon('back')}</a><h1>나의 설정</h1></div><p>나를 표현하는 작은 친구, 나만의 프로필.</p></div><section class="section" style="padding-top:0">${profileSettings()}<form id="personal-profile-form" class="form-box mt-20"><label class="field">대화명<input name="name" required maxlength="40" value="${esc(db.profile.name)}"></label><label class="field">이메일<input type="email" name="email" value="${esc(db.profile.email)}" required></label><button class="primary-btn green full">내 정보 저장</button></form><div class="info-box">${icon('info')}<span>이 브라우저에 저장되는 체험용 프로필입니다.</span></div></section>`+bottomNav()}
function designManager(scope,withTitle=true){const model=designFor(scope),view=viewFor(scope),pool=model[view.kind],slot=pool[view.index]||pool[0],isBanner=view.kind==='banners',site=scope==='site',activeId=isBanner?(site?model.heroSelections[view.target]:model.bannerId):model.backgroundId;return `${withTitle?consoleTitle(site?'방긋마켓 사이트 관리':'기관 쇼핑몰 이미지 관리','생성형 이미지와 실제 인물 사진으로 여백과 배너를 꾸며 보세요.',`<a class="pill-btn" href="#${site?'/':'/institution/'+scope.slice(4)}">${icon('shop')} 미리보기</a>`):''}<div class="design-summary"><span>${icon('leaf')} 여백 이미지 <b>10</b></span><span>${icon('camera')} 배너 이미지 <b>10</b></span><span class="design-summary-scope">${site?'메인 사이트 전용':'이 기관몰 전용'}</span></div><div class="design-kind-tabs" role="tablist" aria-label="디자인 이미지 종류">${[['backgrounds','PC 여백 이미지','leaf'],['banners','상단 배너 이미지','camera']].map(([kind,label,i])=>btn('design-kind',icon(i)+label,'design-kind '+(view.kind===kind?'active':''),`data-kind="${kind}" role="tab" aria-selected="${view.kind===kind}"`)).join('')}</div><div class="design-selected-summary"><span><small>선택한 이미지</small><strong>${esc(slot.label)}</strong></span>${btn('design-edit-scroll','다듬기','pill-btn')}${btn('design-apply','이 이미지 적용','primary-btn green',`data-scope="${esc(scope)}"`)}</div><div class="design-gallery" aria-label="${isBanner?'배너':'여백'} 이미지 10종">${pool.map((item,index)=>{const applied=item.id===activeId;return btn('design-pick',`<div class="design-thumb"><img src="${mediaSource(item)}" alt="${esc(item.alt)}" style="object-position:${item.x}% ${item.y}%" loading="lazy">${applied?'<span class="design-applied">'+icon('check')+' 적용 중</span>':''}${item.uploadId?'<span class="custom-image-label">MY</span>':''}</div><span class="design-slot-number">${String(index+1).padStart(2,'0')}</span><strong>${esc(item.label)}</strong>`,'design-tile '+(index===view.index?'selected':''),`data-index="${index}" aria-label="${String(index+1).padStart(2,'0')} ${esc(item.label)} 선택" aria-pressed="${index===view.index}"`)}).join('')}</div><section class="design-edit-card"><div class="split-row"><div><span class="section-overline">${isBanner?'BANNER IMAGE':'SIDE BACKGROUND'} ${String(view.index+1).padStart(2,'0')}</span><h3>선택한 이미지 다듬기</h3></div>${slot.uploadId?'<span class="mini-badge">내 이미지</span>':`<span class="mini-badge">${slot.source==='photo'?'실제 인물 사진':'생성형 이미지'}</span>`}</div><div class="design-large-preview ${isBanner?'banner-preview':'side-preview'}"><img id="design-edit-preview" src="${mediaSource(slot)}" alt="${esc(slot.alt)}" style="object-position:${slot.x}% ${slot.y}%">${isBanner?'<div class="design-preview-copy"><small>마음을 잇는 방긋마켓</small><strong>좋은 물건에 담긴<br>더 좋은 마음.</strong></div>':'<div class="design-preview-copy"><small>A LITTLE GOOD, A BIG SMILE.</small><strong>작은 마음이 모여,<br>더 큰 방긋으로.</strong></div>'}</div><form id="design-slot-form" data-scope="${esc(scope)}" data-kind="${view.kind}" data-index="${view.index}"><label class="field">이미지 이름<input name="label" value="${esc(slot.label)}" required maxlength="30"></label><label class="field">이미지 설명<input name="alt" value="${esc(slot.alt)}" required maxlength="100"></label><div class="focal-fields"><label class="field">가로 위치 <output id="focal-x-value">${slot.x}%</output><input name="x" data-focal="x" type="range" min="0" max="100" value="${slot.x}"></label><label class="field">세로 위치 <output id="focal-y-value">${slot.y}%</output><input name="y" data-focal="y" type="range" min="0" max="100" value="${slot.y}"></label></div><div class="image-upload-box">${icon('camera')}<div><strong>다른 이미지로 교체하기</strong><span>JPG · PNG · WebP / 최대 12MB</span></div><label class="pill-btn image-upload-label">파일 선택<input id="design-image-upload" type="file" accept="image/jpeg,image/png,image/webp" data-scope="${esc(scope)}" data-kind="${view.kind}" data-index="${view.index}" aria-label="선택한 ${isBanner?'배너':'여백'} 이미지 교체"></label></div><div class="design-edit-buttons"><button class="secondary-btn">이름·구도 저장</button>${btn('design-slot-reset','기본 이미지 복원','secondary-btn',`data-scope="${esc(scope)}"`)}</div></form><div class="design-apply-area">${isBanner&&site?`<label class="field">메인에 적용할 배너 위치<select id="design-hero-target">${[0,1,2,3].map(i=>`<option value="${i}" ${view.target===i?'selected':''}>메인 배너 ${i+1}</option>`).join('')}</select></label>`:''}${!isBanner?`<label class="field">여백 이미지 밝기 <output id="veil-value">${model.veil}%</output><input id="design-veil" type="range" min="10" max="90" value="${model.veil}"><small>밝기를 높이면 문구와 메뉴가 더 또렷하게 보여요.</small></label>`:''}${btn('design-apply',icon('check')+` ${isBanner?(site?'메인 배너 '+(view.target+1):'기관몰 배너'):'PC 여백'}에 적용`,'primary-btn full green',`data-scope="${esc(scope)}"`)}</div></section><div class="info-box">${icon('shield')}<span>${site?'메인 사이트의 디자인만 바뀝니다. 각 기관몰의 선택은 유지됩니다.':'이 기관의 나눔가게만 바뀝니다. 다른 기관몰과 메인 사이트는 그대로예요.'}<br>선택·교체한 이미지는 이 브라우저에서 유지됩니다.</span></div>`}
function mallManagement(){const o=activeOrg();return consoleTitle('우리 기관의 나눔가게를 꾸며요','기관 소개와 이미지로 나눔가게의 첫인상을 만듭니다.',`<a class="pill-btn" href="#/institution/${o.id}">기관몰 보기 ${icon('arrow')}</a>`)+`<div class="mall-management-brand"><span class="org-logo-fixed" style="color:${o.color}">${o.symbol}</span><div><strong>${esc(o.name)}</strong><small>기관 로고 · 계정 프로필과 별도로 유지</small></div></div><details class="mall-info-disclosure"><summary>기관몰 기본 정보·포인트 색상</summary><form id="mall-form" class="form-box mt-20"><label class="field">기관몰 이름<input name="name" required value="${esc(o.name)}" maxlength="40"></label><label class="field">기관몰 한 줄 소개<input name="tag" required value="${esc(o.tag)}" maxlength="50"></label><label class="field">기관 소개<textarea name="description" required maxlength="300">${esc(o.description)}</textarea></label><label class="field">활동 지역·분야<input name="area" required value="${esc(o.area)}" maxlength="50"></label><div class="field">기관 포인트 색상<div class="color-choice">${['#477560','#c99551','#6a7b93','#be805e'].map(c=>btn('mall-color','',o.color===c?'active':'',`style="background:${c}" data-color="${c}" aria-label="색상 ${c}"`)).join('')}</div></div><button class="primary-btn green full">기관몰 기본 정보 저장</button></form></details><div class="mt-20">${designManager('org:'+o.id,false)}</div>`}
function independentMall(id){const o=org(id),design=designFor('org:'+o.id),hero=selectedBanner(design),ps=db.products.filter(p=>p.org===o.id),following=db.follows.includes(o.id);return `<header class="app-header mall-header"><a href="#/institutions" class="icon-btn mall-back" aria-label="전체 기관 쇼핑몰로">${icon('back')}</a><a class="mall-header-brand" href="#/institution/${o.id}"><span class="org-logo-fixed" style="color:${o.color}">${o.symbol}</span><span><small>방긋마켓과 함께하는 나눔가게</small><strong>${esc(o.name)}</strong></span></a><div class="header-actions"><a class="icon-btn" href="#/cart" aria-label="장바구니">${icon('cart')}</a>${btn('roles',db.role?avatarHTML(accountProfile().avatar):icon('user'),'icon-btn','aria-label="내 계정 및 콘솔"')}</div></header><section class="mall-hero"><img src="${mediaSource(hero)}" alt="${esc(hero.alt)}" style="object-position:${hero.x}% ${hero.y}%"><div class="mall-hero-gradient"></div><div class="mall-hero-copy"><span>SHOP WITH A LITTLE HEART</span><h1>${esc(o.tag)}</h1><p>좋은 물건의 다음 주인, 따뜻한 나눔의 시작.</p></div><span class="mall-hero-label">${icon('leaf')} 우리 기관의 나눔가게</span></section><section class="mall-welcome"><div class="mall-welcome-top"><div class="mall-identity"><span class="org-logo-fixed" style="color:${o.color}">${o.symbol}</span><div><span class="verified">${icon('shield')} 사회복지기관 · 예시 기관몰</span><h2>${esc(o.name)}</h2></div></div>${btn('follow',icon('heart')+(following?'응원 중':'응원하기'),'pill-btn '+(following?'on':''),`data-id="${o.id}"`)}</div><p>${esc(o.description)}</p><div class="mall-impact-note">${icon('heart')}<span>당신의 쇼핑이 <b>${esc(o.short||o.name)}</b>의<br>따뜻한 활동에 힘이 됩니다.</span><span class="mall-impact-flower">✳</span></div><div class="mall-quick-stats"><div><b>${ps.length}<small>개</small></b><span>판매 상품</span></div><div><b>${o.followers+(following?1:0)}<small>명</small></b><span>함께하는 마음</span></div><div><b>${Math.round(o.raised/o.goal*100)}<small>%</small></b><span>나눔 진행 · 예시</span></div></div><div class="mall-main-actions"><a href="#/donate?org=${o.id}" class="primary-btn green">${icon('gift')} 이 기관에 현물 기부</a>${btn('org-tab','기관 이야기 '+icon('arrow'),'secondary-btn','data-tab="intro" data-scroll="true"')}</div></section><nav class="org-tabs mall-tabs" aria-label="기관몰 메뉴">${[['goods','판매 상품'],['intro','기관 소개'],['story','나눔 소식'],['report','투명한 나눔']].map(([key,label])=>btn('org-tab',label,orgTab===key?'active':'',`data-tab="${key}"`)).join('')}</nav><section class="section mall-content" id="mall-content">${mallTabContent(o,ps)}</section><section class="mall-giving-banner"><span class="mall-giving-illustration">${icon('gift')}</span><div><small>함께 채우는 우리 기관의 내일</small><h3>물건 하나에, 마음 하나.</h3><p>개인도 기업도, 따뜻한 나눔을 시작해 보세요.</p><a href="#/donate?org=${o.id}">현물 기부하기 ${icon('arrow')}</a></div></section><div class="mall-powered"><img src="/assets/brand/banggeut-icon.png" alt="방긋마켓"><span>이 나눔가게는 방긋마켓과 함께합니다.<br><small>상품·주문·배송은 기관이 관리하고, 라이브는 방긋마켓이 운영해요.</small></span></div>`+footer()+bottomNav()}
function mallTabContent(o,ps){if(orgTab==='goods')return `<div class="section-heading"><div><p class="section-overline">GOOD FINDS, WARM HEARTS</p><h2>매일 열리는 작은 바자회<small>마음에 드는 물건으로 나눔에 함께하세요.</small></h2></div><span class="small muted">${ps.length}개</span></div><div class="product-grid">${ps.length?ps.map(productCard).join(''):empty('새로운 물건을 기다리고 있어요','기부 물품이 등록되면 이곳에서 만날 수 있습니다.')}</div>`;if(orgTab==='intro')return `<div class="story-content"><p class="section-overline">OUR LITTLE STORY</p><h2>우리의 작은 나눔이,<br>이웃의 내일이 되도록.</h2><p>${esc(o.description)}</p><img src="${mediaSource(selectedBanner(designFor('org:'+o.id)))}" alt="${esc(o.name)} 나눔 이야기"><h3>${esc(o.tag)}</h3><p>나눔가게는 기부된 물건이 새로운 주인을 만나고, 그 가치가 우리 기관의 활동에 보탬이 되는 공간입니다. 기관이 상품과 주문·배송을 직접 관리하고, 방긋마켓의 자체 라이브 판매와 정산을 함께 이용합니다.</p><div class="info-box">${icon('building')}<span>활동 분야 · ${esc(o.area)}<br>운영 기관 · ${esc(o.name)} (예시 기관)<br>작은 손길이 모여 더 따뜻한 일상을 만듭니다.</span></div></div>`;if(orgTab==='story')return `<div class="story-content">${publishedNews(o.id)}<p class="section-overline">SMILES WE SHARE</p><h2>함께여서 더 좋은 소식</h2><img src="${asset('people')}" alt="바자회에서 웃으며 물건을 고르는 사람들"><h3>기부에 담긴 마음이 이어집니다.</h3><p>물건이 전해진 이야기와 나눔 활동의 후기를 이곳에 차곡차곡 기록합니다. 응원해 주시는 분들께 기관의 하루와 작은 변화를 전하겠습니다.</p><span class="mini-badge">미리 보는 기관 소식 · 예시 콘텐츠</span></div>`;return `<div class="report-card mall-report"><span class="section-overline">EVERY LITTLE HEART COUNTS</span><h3>소중한 마음이 이렇게 모였어요.</h3><div class="number">${won(o.raised)}</div><div class="progress-track"><span style="width:${Math.min(100,o.raised/o.goal*100)}%"></span></div><div class="split-row small muted"><span>목표 ${won(o.goal)}</span><strong>${Math.round(o.raised/o.goal*100)}%</strong></div><p class="small muted">기관별 나눔 현황을 보여 주는 예시 금액입니다.</p></div><div class="report-card"><h3>물건에 담긴 마음이 닿기까지</h3>${timeline(['현물 기부 접수','기관의 수령·검수','라이브·상시 바자회 판매','배송과 판매 결과 확인','기관 정산과 활동 공유'])}</div>`}
function applyAppearance(){const inside=currentRoute.startsWith('/institution/'),o=inside?org(currentRoute.split('/')[2]):null,design=designFor(o?'org:'+o.id:currentRoute==='/console'&&db.role==='agency'&&consoleSection==='mall'?'org:'+db.orgId:'site'),background=selectedBackground(design),veil=Number(design.veil)/100;const scene=$('.desktop-scene');scene.style.backgroundImage=`linear-gradient(180deg,rgba(249,248,242,.98) 0%,rgba(249,248,242,${Math.min(.97,veil+.28)}) 32%,rgba(249,248,242,${veil}) 100%),url('${mediaSource(background)}')`;scene.style.backgroundPosition=`${background.x}% ${background.y}%`;scene.style.backgroundSize='cover';scene.style.opacity='1';if(o){$('.brand-panel').innerHTML=`<a href="#/institution/${o.id}" class="institution-side-brand"><span class="org-logo-fixed" style="color:${o.color}">${o.symbol}</span><span><small>방긋마켓 기관 쇼핑몰</small><strong>${esc(o.name)}</strong></span></a><div class="institution-side-story"><div class="eyebrow">A LITTLE GIVING, A BETTER TOMORROW.</div><h1>작은 마음이 모여,<br>더 따뜻한<br><span style="color:${o.color}">우리의 내일로.</span></h1><p>${esc(o.tag)}<br>취향을 담은 쇼핑에, 나눔을 더해요.</p><div class="story-label">${icon('leaf')} 함께하는 ${esc(o.name)}</div></div><a class="institution-side-home" href="#/">${icon('bag')} 방긋마켓 전체 보기 ${icon('arrow')}</a>`;$('#desktop-menu').innerHTML=`<p class="rail-label">OUR LITTLE GOOD STORE</p>${[['goods','bag','판매 상품'],['intro','building','기관 소개'],['story','heart','나눔 소식'],['report','chart','투명한 나눔']].map(([key,i,label])=>btn('org-tab',icon(i)+`<span>${label}</span>`,'rail-item '+(orgTab===key?'active':''),`data-tab="${key}" data-scroll="true"`)).join('')}<div class="rail-line"></div><a href="#/institutions" class="rail-item">${icon('shop')} 전체 기관 쇼핑몰</a><a href="#/my" class="rail-item">${icon('user')} 마이 방긋</a><a href="#/donate?org=${o.id}" class="rail-donate" style="background:${o.color}">${icon('gift')} 이 기관에 기부하기</a><div class="rail-note">${esc(o.name)}의<br>새로운 이야기를 함께해요.</div>`}else $('.brand-panel').innerHTML=baseBrandPanel}
function initDesignSystem(){baseBrandPanel=$('.brand-panel').innerHTML;ensureDesignData();save();menus.admin.splice(menus.admin.findIndex(item=>item[0]==='campaigns'),0,['site-design','사이트 관리']);const mallMenu=menus.agency.find(item=>item[0]==='mall');if(mallMenu)mallMenu[1]='기관 쇼핑몰 관리';
const baseHeader=header;header=function(compact=false){const html=baseHeader(compact);return db.role?html.replace(`${icon('user')}` ,avatarHTML(accountProfile().avatar,'header-avatar')):html};
const baseConsole=consoleContent;consoleContent=function(){if(consoleSection==='site-design'&&db.role==='admin')return designManager('site');if(consoleSection==='mall'&&db.role==='agency')return mallManagement();if(consoleSection==='campaigns'&&db.role==='admin')return consoleTitle('메인 배너 4장의 이야기','이미지와 문구를 수정하고 사이트 관리에서 이미지 10종을 교체할 수 있습니다.')+`<div class="data-list">${slides.map((s,i)=>{const setting=designFor('site'),slot=setting.banners.find(item=>item.id===setting.heroSelections[i]);s={...s,...db.banners[i]};return `<div class="data-row"><img src="${mediaSource(slot)}" alt="배너 ${i+1}"><div class="data-row-content"><p>메인 배너 0${i+1}</p><h3>${s.title}</h3></div><div class="data-row-side">${status('노출 중')}${btn('banner-edit','문구·이미지 수정','',`data-index="${i}"`)}</div></div>`}).join('')}</div><div class="button-group mt-20">${btn('console-tab',icon('camera')+' 이미지 10종 관리','secondary-btn','data-section="site-design"')}</div>`;return (consoleSection==='settings'?profileSettings():'')+baseConsole()};
const baseHero=heroHTML;heroHTML=function(){const model=designFor('site'),slot=model.banners.find(item=>item.id===model.heroSelections[slide])||model.banners[slide];return baseHero().replace(/<img class="hero-photo"[^>]*>/,`<img class="hero-photo" src="${mediaSource(slot)}" alt="${esc(slot.alt)}" style="object-position:${slot.x}% ${slot.y}%">`)};
const baseCard=orgCard;orgCard=function(o){const slot=selectedBanner(designFor('org:'+o.id));return baseCard(o).replace(/<img class="org-cover"[^>]*>/,`<img class="org-cover" src="${mediaSource(slot)}" alt="${esc(o.name)} 나눔가게" loading="lazy" style="object-position:${slot.x}% ${slot.y}%">`)};
orgPage=independentMall;
const baseMy=myPage;myPage=function(){return baseMy().replace('<div class="report-card"><div class="split-row">',`<a href="#/profile" class="my-profile-shortcut">${avatarHTML(accountProfile().avatar,'large')}<span><strong>나의 프로필과 설정</strong><small>${esc(avatarNames[accountProfile().avatar-1])} · 캐릭터 변경하기</small></span>${icon('chevron')}</a><div class="report-card"><div class="split-row">`)};
const baseRender=render;render=function(reset=false){ensureDesignData();if(route()==='/profile'){const y=scrollY;currentRoute=route();$('#app').innerHTML=buyerProfilePage();rail();document.body.classList.remove('institution-view');document.title='나의 프로필 설정 · 방긋마켓';window.scrollTo(0,reset?0:y)}else baseRender(reset);applyAppearance()};
Object.assign(actions,{
'org-tab':el=>{orgTab=el.dataset.tab;render();if(el.dataset.scroll)$('#mall-content')?.scrollIntoView({block:'start',behavior:'smooth'})},
'avatar-picker':openAvatarPicker,'avatar-draft-select':el=>updateAvatarDraft(Number(el.dataset.avatar)),'avatar-draft-random':()=>updateAvatarDraft(randomAvatar(avatarDraft)),
'avatar-commit':()=>{if(avatarDraft<1||avatarDraft>30)return;accountProfile().avatar=avatarDraft;save();closeModal();render();toast('방긋 친구를 저장했어요. 기관 로고는 그대로 유지됩니다.')},
'avatar-random-now':()=>{const p=accountProfile();p.avatar=randomAvatar(p.avatar);save();render();toast(avatarNames[p.avatar-1]+' 친구를 만났어요.')},
'design-edit-scroll':()=>$('.design-edit-card')?.scrollIntoView({block:'start',behavior:'smooth'}),
'design-kind':el=>{const scope=scopeForEditor();if(!scope||!['backgrounds','banners'].includes(el.dataset.kind))return;const view=viewFor(scope);view.kind=el.dataset.kind;view.index=0;render()},
'design-pick':el=>{const scope=scopeForEditor();if(!scope)return;viewFor(scope).index=Math.min(9,Math.max(0,Number(el.dataset.index)));render()},
'design-apply':el=>{const scope=el.dataset.scope;if(!canEditScope(scope))return;const model=designFor(scope),view=viewFor(scope),slot=model[view.kind][view.index];const f=$('#design-slot-form');if(f&&!f.reportValidity())return;if(f){const data=Object.fromEntries(new FormData(f));Object.assign(slot,{label:data.label,alt:data.alt,x:Number(data.x),y:Number(data.y)})}if(view.kind==='backgrounds'){model.backgroundId=slot.id;model.veil=Number($('#design-veil')?.value||model.veil)}else if(scope==='site')model.heroSelections[view.target]=slot.id;else model.bannerId=slot.id;save();render();toast((view.kind==='backgrounds'?'PC 여백 이미지':'배너 이미지')+'를 적용했습니다.')},
'design-slot-reset':el=>{const scope=el.dataset.scope;if(!canEditScope(scope))return;const view=viewFor(scope),model=designFor(scope);model[view.kind][view.index]=structuredClone(seedDesign(scope)[view.kind][view.index]);save();render();toast('선택한 칸을 기본 생성 이미지로 복원했습니다.')},
'banner-edit':el=>{if(db.role!=='admin')return;const i=Number(el.dataset.index),s={...slides[i],...db.banners[i]},design=designFor('site'),selected=design.heroSelections[i];openModal('메인 배너 '+(i+1)+' 수정',`<form id="banner-form" data-index="${i}"><label class="field">배너 제목 · 줄바꿈 가능<textarea name="title" required maxlength="60">${esc(s.title.replace(/<br>/g,'\n'))}</textarea></label><label class="field">소개 문구<textarea name="desc" required maxlength="100">${esc(s.desc.replace(/<br>/g,'\n'))}</textarea></label><label class="field">배너 이미지 · 기본 10종<select name="image">${design.banners.map(slot=>`<option value="${slot.file}" ${slot.id===selected?'selected':''}>${esc(slot.label)}</option>`).join('')}</select></label><button class="primary-btn full green">배너 저장</button></form>`)},
});
document.addEventListener('submit',e=>{const f=e.target,values=Object.fromEntries(new FormData(f));if(f.id==='design-slot-form'){e.preventDefault();const scope=f.dataset.scope;if(!canEditScope(scope))return;const slot=designFor(scope)[f.dataset.kind][Number(f.dataset.index)];Object.assign(slot,{label:values.label,alt:values.alt,x:Number(values.x),y:Number(values.y)});save();render();toast('이미지 이름과 구도를 저장했습니다.')}else if(f.id==='personal-profile-form'){e.preventDefault();Object.assign(db.profile,values);save();render();toast('내 정보를 저장했어요.')}else if(f.id==='banner-form'&&db.role==='admin'){const model=designFor('site'),slot=model.banners.find(item=>item.file===values.image);if(slot){model.heroSelections[Number(f.dataset.index)]=slot.id;save();render()}}});
document.addEventListener('change',async e=>{if(e.target.id==='design-hero-target'){const scope=scopeForEditor();if(scope!=='site')return;viewFor(scope).target=Number(e.target.value);render()}if(e.target.id==='design-image-upload'){const input=e.target,scope=input.dataset.scope,kind=input.dataset.kind,index=Number(input.dataset.index),file=input.files[0];if(!file||!canEditScope(scope))return;const label=input.closest('.image-upload-label');label.classList.add('busy');try{toast('이미지를 준비하고 있어요.');const id=await storeUploadedImage(file);if(!canEditScope(scope))return;const slot=designFor(scope)[kind][index];const f=$('#design-slot-form');if(f){const data=Object.fromEntries(new FormData(f));Object.assign(slot,{label:data.label,alt:data.alt,x:Number(data.x),y:Number(data.y)})}slot.uploadId=id;save();render();toast('선택한 이미지를 교체했습니다. 적용 버튼으로 사용할 위치를 정해 주세요.')}catch(error){toast(error.message)}finally{label.classList.remove('busy')}}});
document.addEventListener('input',e=>{if(e.target.dataset.focal){const f=e.target.closest('form'),x=f.elements.x.value,y=f.elements.y.value;$('#design-edit-preview').style.objectPosition=`${x}% ${y}%`;$('#focal-x-value').textContent=x+'%';$('#focal-y-value').textContent=y+'%'}if(e.target.id==='design-veil'){$('#veil-value').textContent=e.target.value+'%';const design=designFor(scopeForEditor()),slot=selectedBackground(design),veil=Number(e.target.value)/100;$('.desktop-scene').style.backgroundImage=`linear-gradient(180deg,rgba(249,248,242,.98),rgba(249,248,242,${veil})),url('${mediaSource(slot)}')`}});
const baseReset=actions['confirm-reset'];actions['confirm-reset']=()=>{baseReset();save()};
loadUploadedImages();
}
